package com.rulecraft.decisionops.tests;

import static org.assertj.core.api.Assertions.assertThat;import static org.assertj.core.api.Assertions.assertThatThrownBy;
import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.*;import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.ExpressionCommand;import com.rulecraft.decisionops.graph.DecisionGraphService;import com.rulecraft.decisionops.graph.DecisionGraphService.*;import com.rulecraft.decisionops.graph.domain.*;import com.rulecraft.decisionops.identity.domain.*;import com.rulecraft.decisionops.identity.persistence.UserAccountRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectService;import com.rulecraft.decisionops.projects.domain.ProjectRole;import com.rulecraft.decisionops.tests.DecisionTestService.*;import com.rulecraft.decisionops.tests.domain.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.crypto.password.PasswordEncoder;import tools.jackson.databind.*;

@SpringBootTest
class DecisionTestIntegrationTest {
    @Autowired DecisionTestService decisionTests;@Autowired DecisionExpressionService expressions;@Autowired DecisionGraphService graphs;@Autowired CatalogService catalog;@Autowired ProjectService projects;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwordEncoder;@Autowired Clock clock;@Autowired JdbcClient jdbc;@Autowired ObjectMapper mapper;RuleCraftPrincipal admin;
    @BeforeEach void actor(){admin=new RuleCraftPrincipal(users.findForLogin("acme-rules","admin@example.test").orElseThrow(),"acme-rules");}

    @Test void persistsVersionedScenarioAndImmutablePassFailHistory(){var fixture=fixture();var auditBefore=jdbc.sql("select count(*) from audit_event where action = 'DECISION_TEST_EXECUTED'").query(Long.class).single();var created=decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),command(null,"highScore","High score","750","true"));assertThat(created.validationStatus()).isEqualTo(TestCaseValidationStatus.VALID);var passed=decisionTests.run(admin,fixture.projectId(),fixture.serviceId(),created.id());assertThat(passed.status()).isEqualTo(TestRunStatus.PASSED);assertThat(passed.decisions()).extracting("implementation").containsExactly("EXPRESSION");var changed=decisionTests.update(admin,fixture.projectId(),fixture.serviceId(),created.id(),command(created.version(),"highScore","High score","750","false"));var failed=decisionTests.run(admin,fixture.projectId(),fixture.serviceId(),created.id());assertThat(failed.status()).isEqualTo(TestRunStatus.FAILED);assertThat(failed.testCaseVersion()).isEqualTo(changed.version());assertThat(decisionTests.history(admin,fixture.projectId(),fixture.serviceId(),created.id())).extracting("status").containsExactly(TestRunStatus.FAILED,TestRunStatus.PASSED);assertThat(decisionTests.list(admin,fixture.projectId(),fixture.serviceId()).getFirst().latestRun().status()).isEqualTo(TestRunStatus.FAILED);assertThat(jdbc.sql("select count(*) from audit_event where action = 'DECISION_TEST_EXECUTED'").query(Long.class).single()).isEqualTo(auditBefore+2);decisionTests.remove(admin,fixture.projectId(),fixture.serviceId(),created.id(),changed.version());assertThat(decisionTests.list(admin,fixture.projectId(),fixture.serviceId())).isEmpty();}

    @Test void rejectsInvalidDuplicateAndStaleChangesWithStableCodes(){var fixture=fixture();var created=decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),command(null,"baseline","Baseline","700","true"));assertCode("RC-TEST-KEY-EXISTS",()->decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),command(null,"baseline","Duplicate","500","false")));assertCode("RC-TEST-INPUT-TYPE",()->decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),command(null,"badType","Bad type","\"high\"","true")));assertCode("RC-TEST-OUTPUT-UNKNOWN",()->decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),new TestCaseCommand(null,"badOutput","Bad output",null,Map.of("score",mapper.readTree("700")),Map.of("other",mapper.readTree("true")))));decisionTests.update(admin,fixture.projectId(),fixture.serviceId(),created.id(),command(created.version(),"baseline","Changed","650","true"));assertCode("RC-TEST-STALE",()->decisionTests.update(admin,fixture.projectId(),fixture.serviceId(),created.id(),command(created.version(),"baseline","Stale","600","true")));}

    @Test void detectsContractDriftBeforeExecution(){var fixture=fixture();var created=decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),command(null,"driftCase","Drift case","700","true"));var service=catalog.getService(admin,fixture.projectId(),fixture.serviceId());catalog.updateService(admin,fixture.projectId(),fixture.serviceId(),new DecisionServiceCommand(service.serviceKey(),service.name(),service.description(),List.of(new FieldCommand("score","Score",builtin(BuiltinType.TEXT),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),service.version()));var drifted=decisionTests.list(admin,fixture.projectId(),fixture.serviceId()).getFirst();assertThat(drifted.validationStatus()).isEqualTo(TestCaseValidationStatus.INVALID);assertThat(drifted.issues()).extracting("code").contains("RC-TEST-INPUT-TYPE");assertCode("RC-TEST-INVALID",()->decisionTests.run(admin,fixture.projectId(),fixture.serviceId(),created.id()));}

    @Test void viewerCanReadAndRunButCannotAuthorAndOutsiderCannotDiscover(){var fixture=fixture();var created=decisionTests.create(admin,fixture.projectId(),fixture.serviceId(),command(null,"viewerCase","Viewer case","750","true"));var now=Instant.now(clock);var viewerAccount=users.save(new UserAccount(admin.tenantId(),"test-viewer"+UUID.randomUUID()+"@example.test","Tess Test Viewer",passwordEncoder.encode("CorrectHorseBattery92!"),TenantRole.MEMBER,now));projects.upsertMember(admin,fixture.projectId(),viewerAccount.getId(),ProjectRole.VIEWER);var viewer=new RuleCraftPrincipal(viewerAccount,"acme-rules");assertThat(decisionTests.list(viewer,fixture.projectId(),fixture.serviceId())).hasSize(1);assertThat(decisionTests.run(viewer,fixture.projectId(),fixture.serviceId(),created.id()).status()).isEqualTo(TestRunStatus.PASSED);assertCode("RC-PROJECT-EDIT-FORBIDDEN",()->decisionTests.create(viewer,fixture.projectId(),fixture.serviceId(),command(null,"forbidden","Forbidden","700","true")));var outsiderAccount=users.save(new UserAccount(admin.tenantId(),"test-outsider"+UUID.randomUUID()+"@example.test","Omar Outsider",passwordEncoder.encode("CorrectHorseBattery93!"),TenantRole.MEMBER,now));var outsider=new RuleCraftPrincipal(outsiderAccount,"acme-rules");assertCode("RC-PROJECT-NOT-FOUND",()->decisionTests.list(outsider,fixture.projectId(),fixture.serviceId()));}

    private Fixture fixture(){var project=projects.create(admin,key("P"),"Decision tests",null);var service=catalog.createService(admin,project.id(),new DecisionServiceCommand(key("SVC"),"Eligibility tests",null,List.of(new FieldCommand("score","Score",builtin(BuiltinType.NUMBER),true)),List.of(new FieldCommand("approved","Approved",builtin(BuiltinType.BOOLEAN),true)),null));var graph=graphs.initialize(admin,project.id(),service.id());var nodeId=UUID.randomUUID();var input=port(GraphPortDirection.INPUT,"score",BuiltinType.NUMBER);var output=port(GraphPortDirection.OUTPUT,"approved",BuiltinType.BOOLEAN);var serviceInput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.INPUT).findFirst().orElseThrow().ports().getFirst();var serviceOutput=graph.nodes().stream().filter(node->node.kind()==GraphNodeKind.OUTPUT).findFirst().orElseThrow().ports().getFirst();var nodes=new ArrayList<NodeCommand>();graph.nodes().forEach(node->nodes.add(command(node)));nodes.add(new NodeCommand(nodeId,"threshold","Approval threshold",GraphNodeKind.DECISION,null,300,100,List.of(input,output)));graphs.update(admin,project.id(),service.id(),new GraphCommand(graph.version(),nodes,List.of(edge(serviceInput.id(),input.id()),edge(output.id(),serviceOutput.id()))));var expression=expressions.initialize(admin,project.id(),service.id(),nodeId);expressions.update(admin,project.id(),service.id(),nodeId,new ExpressionCommand(expression.version(),"score >= 700"));return new Fixture(project.id(),service.id());}
    private TestCaseCommand command(Long version,String key,String name,String input,String expected){return new TestCaseCommand(version,key,name,null,Map.of("score",mapper.readTree(input)),Map.of("approved",mapper.readTree(expected)));}private CatalogService.TypeRefCommand builtin(BuiltinType type){return new CatalogService.TypeRefCommand(type,null);}private PortCommand port(GraphPortDirection direction,String key,BuiltinType type){return new PortCommand(UUID.randomUUID(),direction,key,key,new DecisionGraphService.TypeRefCommand(type,null),true,0);}private NodeCommand command(GraphNodeView node){return new NodeCommand(node.id(),node.nodeKey(),node.name(),node.kind(),node.serviceFieldKey(),node.positionX(),node.positionY(),node.ports().stream().map(port->new PortCommand(port.id(),port.direction(),port.portKey(),port.label(),port.type(),port.required(),port.position())).toList());}private EdgeCommand edge(UUID source,UUID target){return new EdgeCommand(UUID.randomUUID(),source,target);}private String key(String prefix){return prefix+UUID.randomUUID().toString().replace("-","").substring(0,8).toUpperCase();}private void assertCode(String code,Runnable action){assertThatThrownBy(action::run).isInstanceOf(DomainProblemException.class).extracting("code").isEqualTo(code);}private record Fixture(UUID projectId,UUID serviceId){}
}
